mapper.select:
SELECT COUNT(*)
FROM material_processing_revision r
JOIN material_version v ON v.id = r.version_id
JOIN material m ON m.id = v.material_id
JOIN material_processing_job j ON j.revision_id = r.id
WHERE r.id = #{revisionId}
  AND r.fence_generation = #{expectedGeneration}
  AND m.lifecycle_generation = #{materialLifecycleGeneration}
  AND r.state = 'PROCESSING'
  AND v.ingest_state = 'PROCESSING'
  AND m.lifecycle_state = 'ACTIVE'
  AND (m.retention_class = 'RETAINED' OR m.expires_at > UTC_TIMESTAMP(3))
  AND j.id = #{jobId}
  AND j.stage = #{expectedStage}
  AND j.status = 'RUNNING'
  AND j.lease_owner = #{workerId}
  AND j.fence_token = #{fenceToken}
  AND j.lease_until > UTC_TIMESTAMP(3)
FOR UPDATE

mapper.insert:
INSERT IGNORE INTO material_page (
    id, revision_id, page_no, width, height, native_text_status, ocr_status,
    ocr_quality, visual_status, page_image_key, raw_extraction_key, canonical_page_key
) VALUES (
    #{id}, #{revisionId}, #{pageNo}, #{width}, #{height}, #{nativeTextStatus}, #{ocrStatus},
    #{ocrQuality}, #{visualStatus}, #{pageImageKey}, #{rawExtractionKey}, #{canonicalPageKey}
)

INSERT IGNORE INTO material_page_artifact (
    id, revision_id, page_no, artifact_kind, object_key, object_version_id,
    content_sha256, byte_size, content_type
) VALUES (
    #{id}, #{revisionId}, #{pageNo}, #{artifactKind}, #{objectKey}, #{objectVersionId},
    #{contentSha256}, #{byteSize}, #{contentType}
)

mapper.update:
UPDATE material_page
SET canonical_page_key = #{canonicalPageKey}
WHERE revision_id = #{revisionId} AND page_no = #{pageNo}
  AND canonical_page_key IS NULL

mapper.insert:
INSERT IGNORE INTO material_revision_artifact (
    id, revision_id, artifact_kind, object_key, object_version_id,
    content_sha256, byte_size, content_type
) VALUES (
    #{id}, #{revisionId}, #{artifactKind}, #{objectKey}, #{objectVersionId},
    #{contentSha256}, #{byteSize}, #{contentType}
)

INSERT IGNORE INTO material_section (
    id, revision_id, parent_section_id, level, ordinal, page_start, page_end,
    heading_evidence_id, structure_hash
) VALUES (
    #{id}, #{revisionId}, #{parentSectionId}, #{level}, #{ordinal}, #{pageStart}, #{pageEnd},
    #{headingEvidenceId}, #{structureHash}
)

INSERT IGNORE INTO material_visual_artifact (
    revision_id, candidate_id, page_id, page_no, caption_block_id,
    object_key, object_version_id, content_sha256, byte_size, content_type
) VALUES (
    #{revisionId}, #{candidateId}, #{pageId}, #{pageNo}, #{captionBlockId},
    #{objectKey}, #{objectVersionId}, #{contentSha256}, #{byteSize}, #{contentType}
)

INSERT IGNORE INTO evidence_unit (
    id, version_id, revision_id, page_id, section_id, unit_type, modality, source_channel,
    display_text_object_key, display_text_object_version_id,
    visual_object_key, visual_object_version_id, display_text_sha256, quality_json, status
) VALUES (
    #{id}, #{versionId}, #{revisionId}, #{pageId}, #{sectionId}, #{unitType}, #{modality}, #{sourceChannel},
    #{displayTextObjectKey}, #{displayTextObjectVersionId},
    #{visualObjectKey}, #{visualObjectVersionId}, #{displayTextSha256}, #{qualityJson}, #{status}
)

INSERT IGNORE INTO evidence_region (
    evidence_id, page_id, ordinal, bbox_json, display_char_start, display_char_end, source_block_ref
) VALUES (
    #{evidenceId}, #{pageId}, #{ordinal}, #{bboxJson},
    #{displayCharStart}, #{displayCharEnd}, #{sourceBlockRef}
)

INSERT IGNORE INTO evidence_relation (
    from_evidence_id, to_evidence_id, relation_type, weight
) VALUES (
    #{fromEvidenceId}, #{toEvidenceId}, #{relationType}, #{weight}
)

mapper.select:
SELECT * FROM evidence_relation
WHERE from_evidence_id = #{fromEvidenceId}
  AND to_evidence_id = #{toEvidenceId}
  AND relation_type = #{relationType}

mapper.update:
UPDATE material_section SET heading_evidence_id = #{evidenceId}
WHERE revision_id = #{revisionId} AND id = #{sectionId}
  AND (heading_evidence_id IS NULL OR heading_evidence_id = #{evidenceId})

