INSERT IGNORE INTO retrieval_exact_term (
    retrieval_chunk_id, owner_type, owner_key, version_id, revision_id, normalized_term, term_type
) VALUES (
    #{retrievalChunkId}, #{ownerType}, #{ownerKey}, #{versionId}, #{revisionId},
    #{normalizedTerm}, #{termType}
)

mapper.select:
SELECT * FROM retrieval_exact_term
WHERE retrieval_chunk_id = #{chunkId}
  AND normalized_term = #{normalizedTerm}
  AND term_type = #{termType}
